// Jodie: readable forward claws and bounded autonomous companion attacks.
const isJodie=()=>selected==='jodie';
let cats=[];
const jodieNames=['Long Claws','Quick Paws','Pouncing Partner','Double Trouble','Cat Frenzy'];
const jodieText=['Longer claw swipes give you safer reach.','Faster double scratches.','Your black cat gains longer, stronger pounces.','Finishing a claw combo calls your black cat into a stronger follow-up pounce.','Three quick alternating claw strikes, with faster assistance from your cat.'];
