const clawReach=()=>tier>=1?62:45;
function makeCat(kitten=false,index=0){let a=index*TAU/6;return {x:p.x+Math.cos(a)*25,y:p.y+Math.sin(a)*25,r:kitten?6:8,kitten,slot:index,mode:'follow',cool:kitten?index*.09:.3,life:kitten?5:Infinity,attempts:0,t:0,boost:false};}
