function kittenChaos(){if(state!=='playing'||p.action||p.chargeCD>0)return;p.chargeCD=12;cats=cats.filter(c=>!c.kitten);for(let i=0;i<6;i++)cats.push(makeCat(true,i));float(p.x,p.y-38,'KITTEN CHAOS!','#eeb6b0');pop(p.x,p.y,'#d7c086',18);}
function startClaws(){if(p.claws)return false;let e=nearest(p,new Set(),clawReach()+50);if(!e||dist(p,e)>clawReach()+e.r+8)return false;let hit=tier>=2?.15:.20,gap=tier>=2?.21:.29,count=tier>=5?3:2;p.claws={t:0,aim:Math.atan2(e.y-p.y,e.x-p.x),wind:.10,hit,gap,count,seen:new Set(),target:e,duration:.10+(count-1)*gap+hit+.10};p.catTarget=e;return true;}
function clawHands(){let s=p.claws;return [0,1].map(i=>{let h={x:i?-19:19,y:2,size:3.8,moving:false};if(!s)return h;for(let n=i;n<s.count;n+=2){let local=s.t-s.wind-n*s.gap;if(local<-.10||local>s.hit+.1)continue;let u=clamp(local/s.hit,0,1),a=s.aim+(i?-1:1)*(.80-1.60*u),w=local<0?1+local/.10:local>s.hit?1-(local-s.hit)/.10:1;h={x:lerp(h.x,Math.cos(a)*clawReach(),w),y:lerp(2,Math.sin(a)*clawReach(),w),size:lerp(3.8,6,w),moving:local>=0&&local<=s.hit,a};}return h;});}
function updateClaws(dt){let s=p.claws;if(!s)return;let before=s.t;s.t+=dt;for(let n=0;n<s.count;n++){let start=s.wind+n*s.gap,from=before-start,to=s.t-start;if(to<0||from>s.hit)continue;let sign=n%2?-1:1,a=s.aim+sign*(.80-1.60*clamp(from/s.hit,0,1)),b=s.aim+sign*(.80-1.60*clamp(to/s.hit,0,1));for(let e of enemies){let key=n+':'+e.id;if(e.hp<=0||s.seen.has(key)||!angularContact(e,Math.min(a,b),Math.max(a,b),0,clawReach()))continue;s.seen.add(key);let d=dist(p,e)||1;damageEnemy(e,10,(e.x-p.x)/d,(e.y-p.y)/d);}}if(s.t>=s.duration){p.claws=null;if(tier>=4){let c=cats.find(c=>!c.kitten);if(c){if(c.mode==='follow'){c.cool=0;c.boost=true;}else c.assistPending=true;}}}}
function chooseCatTarget(c){let marked=p.catTarget;if(marked?.hp>0&&dist(c,marked)<260&&dist(p,marked)<320)return marked;let ranged=null;for(let e of enemies)if(e.hp>0&&e.kind==='mud'&&dist(p,e)<300&&(!ranged||dist(c,e)<dist(c,ranged)))ranged=e;return ranged||nearest(c,new Set(),c.kitten?220:260);}
