function updateCats(dt){if(!isJodie())return;updateClaws(dt);for(let c of cats){c.life-=dt;c.cool-=dt;if(c.mode==='follow'){let e=chooseCatTarget(c),leash=dist(c,p)>300;if(!leash&&e&&c.cool<=0&&dist(c,e)<(c.kitten?95:tier>=3?150:48)+e.r)beginPounce(c,e);else{let a=c.slot*TAU/6+time*.2,goal=(!leash&&e&&c.cool<=0)?e:{x:p.x+Math.cos(a)*(c.kitten?36:30),y:p.y+14+Math.sin(a)*18},d=dist(c,goal)||1,speed=c.kitten?190:175,move=Math.min(Math.max(0,d-13),speed*dt);c.x+=(goal.x-c.x)/d*move;c.y+=(goal.y-c.y)/d*move;}}
else{c.t+=dt;if(c.mode==='wind'&&c.t>=.12){c.mode='pounce';c.t=0;}else if(c.mode==='pounce'){let u=clamp(c.t/.20,0,1);c.x=lerp(c.sx,c.tx,u);c.y=lerp(c.sy,c.ty,u);if(u>=1){let e=c.target;if(e?.hp>0&&dist(c,e)<e.r+c.r+12){let damage=c.kitten?6:(8+tier*2)*(c.boost?1.5:1);if(c.kitten&&e.kind==='boss')damage*=.65;damageEnemy(e,damage,0,0);pop(c.x,c.y,'#e9ceb2',4);c.hit=true;}c.mode='recover';c.t=0;c.boost=false;c.cool=c.kitten?.5:tier>=5?.5:.9;}}else if(c.mode==='recover'&&c.t>=.22){c.mode='follow';if(c.assistPending){c.assistPending=false;c.boost=true;c.cool=0;}}}
let q=walkable(c.x,c.y,c.r);c.x=q.x;c.y=q.y;}
// Separate kittens without teleporting or crowding the main character.
for(let i=0;i<cats.length;i++)for(let j=i+1;j<cats.length;j++){let a=cats[i],b=cats[j];if(a.mode==='pounce'||b.mode==='pounce')continue;let dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy)||1,m=a.r+b.r+4;if(d<m){let n=(m-d)*Math.min(1,dt*12)*.5;a.x-=dx/d*n;a.y-=dy/d*n;b.x+=dx/d*n;b.y+=dy/d*n;}}
cats=cats.filter(c=>!c.kitten||(c.life>0&&(c.attempts<3||c.mode!=='follow')));}
